const {Storage}=require('./storage.cjs');
const {Waiters}=require('./waiters.cjs');
class Channel {
  constructor(capacity){this.buffer=new Storage(capacity);this.readers=new Waiters();this.closed=false;}
  async send(value){
    if(this.closed) throw new Error('closed');
    if(this.readers.size) this.readers.shift()({value,done:false});
    else this.buffer.push(value);
  }
  async receive(){
    if(this.buffer.size) return {value:this.buffer.shift(),done:false};
    if(this.closed) return {value:undefined,done:true};
    return new Promise(resolve=>this.readers.push(resolve));
  }
  close(){this.closed=true;}
}
module.exports={Channel};

