const test=require('node:test');
const assert=require('node:assert/strict');
const {Channel}=require('../channel/service.cjs');
test('backpressure and sender FIFO',{timeout:5000},async()=>{
  const ch=new Channel(1);
  await ch.send(0);
  let secondDone=false,thirdDone=false;
  const second=ch.send(false).then(()=>{secondDone=true;});
  const third=ch.send(undefined).then(()=>{thirdDone=true;});
  await Promise.resolve();await Promise.resolve();
  assert.equal(secondDone,false);assert.equal(thirdDone,false);
  assert.deepEqual(await ch.receive(),{value:0,done:false});
  await second;
  assert.equal(thirdDone,false);
  assert.deepEqual(await ch.receive(),{value:false,done:false});
  await third;
  assert.deepEqual(await ch.receive(),{value:undefined,done:false});
  ch.close();
  assert.deepEqual(await ch.receive(),{value:undefined,done:true});
});
test('receiver FIFO and close waiting receivers',{timeout:5000},async()=>{
  const ch=new Channel(2);
  const a=ch.receive(),b=ch.receive();
  await ch.send('first');await ch.send('second');
  assert.deepEqual(await a,{value:'first',done:false});
  assert.deepEqual(await b,{value:'second',done:false});
  const c=ch.receive(),d=ch.receive();
  ch.close();ch.close();
  assert.deepEqual(await c,{value:undefined,done:true});
  assert.deepEqual(await d,{value:undefined,done:true});
  await assert.rejects(ch.send('late'),{message:'closed'});
});
test('close rejects waiting writers but drains existing data',{timeout:5000},async()=>{
  const ch=new Channel(1);await ch.send('kept');
  const a=ch.send('drop-a'),b=ch.send('drop-b');
  const rejectedA=assert.rejects(a,{message:'closed'}),rejectedB=assert.rejects(b,{message:'closed'});
  ch.close();
  await Promise.all([rejectedA,rejectedB]);
  assert.deepEqual(await ch.receive(),{value:'kept',done:false});
  assert.deepEqual(await ch.receive(),{value:undefined,done:true});
  assert.deepEqual(await ch.receive(),{value:undefined,done:true});
});
test('capacity validation',()=>{
  for(const capacity of [0,-1,1.5,NaN,Infinity]) assert.throws(()=>new Channel(capacity),RangeError);
});

