const {Storage}=require('./storage.cjs');
const {Waiters}=require('./waiters.cjs');
class Channel {
  constructor(capacity){
    if(!Number.isInteger(capacity)||capacity<=0) throw new RangeError('invalid capacity');
    this.buffer=new Storage(capacity);
    this.readers=new Waiters();this.writers=new Waiters();this.closed=false;
  }
  async send(value){
    if(this.closed) throw new Error('closed');
    if(this.readers.size) {this.readers.shift()({value,done:false});return;}
    if(!this.buffer.full) {this.buffer.push(value);return;}
    return new Promise((resolve,reject)=>this.writers.push({value,resolve,reject}));
  }
  async receive(){
    if(this.buffer.size){
      const value=this.buffer.shift();
      if(!this.closed && this.writers.size){
        const writer=this.writers.shift();
        this.buffer.push(writer.value);writer.resolve();
      }
      return {value,done:false};
    }
    if(this.closed) return {value:undefined,done:true};
    return new Promise(resolve=>this.readers.push(resolve));
  }
  close(){
    if(this.closed) return;
    this.closed=true;
    while(this.writers.size) this.writers.shift().reject(new Error('closed'));
    if(!this.buffer.size) while(this.readers.size) this.readers.shift()({value:undefined,done:true});
  }
}
module.exports={Channel};

